def is_prime(n):
    if n < 2:
        return False
    i = 2
    while i * i <= n:
        if n % i == 0:
            return False
        i += 1
    return True

print(is_prime(17))  # True
print(is_prime(15))  # False

def factorial(n):
    if n < 0:
        raise ValueError('factorial of negative number')
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result

print(factorial(5))  # 120

# Recursive version
def fact_rec(n):
    return 1 if n <= 1 else n * fact_rec(n - 1)

